export const calcGap=s=>Math.max(0,Math.round((s.futureDemand-s.candidateSupply)/s.futureDemand*100))
export const gapClassification=s=>{let gap=calcGap(s);return gap>45?'High':gap>=30?'Moderate':'Low'}
